const outlineCache = new Map();

export function getSlabOutline(crop) {
  const key = [crop.asset, crop.x, crop.y, crop.w, crop.h].join(':');
  if (outlineCache.has(key)) return outlineCache.get(key);
  const sourcePoints = SOURCE_OUTLINE_POINTS[key];
  if (!sourcePoints) return null;
  const points = Object.freeze(sourcePoints.map(([x, y]) => Object.freeze([x, y])));
  const percent = value => Number(value.toFixed(5));
  const clipPath = `polygon(${points.map(([x, y]) => `${percent(x / crop.w * 100)}% ${percent(y / crop.h * 100)}%`).join(',')})`;
  const outline = Object.freeze({ width: crop.w, height: crop.h, points, clipPath });
  outlineCache.set(key, outline);
  return outline;
}
